 const values={LEGAL_LIFECYCLE:'ACTIVE',LEGAL_ADDRESS_UNRELIABLE:false,LEGAL_ACTIVE_ENFORCEMENT_AMOUNT:0,LEGAL_ENFORCEMENT_REVENUE_RATIO:0,LEGAL_DEFENDANT_CASES:0,LEGAL_REGISTRY_REVIEW:0,LEGAL_VIOLATIONS_REPORTED:0,FIN_EQUITY:5000000,FIN_REPORTED_NET_ASSETS:5000000,FIN_NET_ASSETS_PROXY:5000000,FIN_CURRENT_ASSETS:10000000,FIN_CURRENT_RATIO:2,FIN_WORKING_CAPITAL:5000000,FIN_ANNUAL_NET_PROFIT:1000000,FIN_ANNUAL_REVENUE:10000000,FIN_CONSECUTIVE_ANNUAL_LOSSES:0,FIN_ANNUAL_REVENUE_CHANGE:5,FIN_INTEREST_COVERAGE:5,BANK_DEBT_SERVICE_RATIO:.1,BANK_COVERAGE_ADEQUATE:true,BANK_OPERATING_TREND:5,BANK_TOP1:.2,BANK_CONCENTRATION_COVERAGE:1,BANK_IDENTITY_COVERAGE:1,BANK_INTERMEDIATED_SHARE:0,BANK_UNKNOWN_INFLOW_SHARE:0,BANK_UNCLEAR_CASH_SHARE:0,BANK_NEGATIVE_RECONSTRUCTED_DAYS:0,BANK_LOW_LIQUIDITY_SHARE:0,BKI_OVERDUE:0,BKI_HISTORY_DAYS:0,PORTFOLIO_UNRESOLVED:0,PORTFOLIO_UNKNOWN_FUNDED:0,PORTFOLIO_CONFLICTS:0,PORTFOLIO_NEW:0,PORTFOLIO_UNMATCHED:0,PORTFOLIO_UNSPLIT:0,RECON_IDENTITY_CONFLICTS:0,RECON_SAME_FACT_CONFLICTS:0,RECON_OTHER_REVIEW:0,SOURCE_MISSING_COUNT:0,SOURCE_STALE_COUNT:0,SOURCE_FAILED_COUNT:0,INTEGRITY_CONFIDENCE:100,BANK_COVERAGE_ISSUE:0,...overrides};
 return Object.entries(values).map(([code,value])=>F(code,value,{...(code.startsWith('BKI_')?{subjectKey:'synthetic-loan'}:{}),...(code==='FIN_NET_ASSETS_PROXY'?{origin:'PROXY'}:{})}));
